                || keeper_ == admin_ || keeper_ == guardian_ || treasury_ == address(0)
                || buyback_ == address(0) || minL == 0 || address(oracle).code.length == 0
                || swapLossBps == 0 || swapLossBps > 500 || bytes(name_).length == 0
                || bytes(symbol_).length == 0
