        a = token0.balanceOf(address(this)) - protocolFees[0] - buybackFees[0] - quarantined[0];
        b = token1.balanceOf(address(this)) - protocolFees[1] - buybackFees[1] - quarantined[1];
        if (caseOpened[0]) a = 0;
        if (caseOpened[1]) b = 0;
