        int24 lo,
        int24 hi,
        uint128 target,
        uint256 nonce,
        uint256 configuration,
        uint256 deadline,
        RebalanceSwap calldata swap
    ) external nonReentrant returns (RebalanceResult) {
        return _rebalance(lo, hi, target, nonce, configuration, deadline, swap);
